-- ─────────────────────────────────────────────────────────────
--  THE OLD WEBSITE'S NEWS — part 5 of 7: 67 articles kept as drafts (not live)
--  Generated by scripts/import-old-news.py from Rich's export of the old WordPress database.
--  Run the news files in order, after the other files in supabase/legacy/ (SQL Editor → paste → Run), each once.
--
--  All 528 old articles: 186 league and competition articles from 2019 on go live, with their real dates.
--  The other 342 wait in Admin → News as drafts (Rich, round 30): Professional Snooker, CueViews,
--  Snooker Memories, and the old archive — whose articles all carry the date 1 January 2014 on the old site
--  (their real dates were lost long ago). Tick "Published" on any of them to put it on the website.
--  The text keeps its paragraphs, the opening paragraph and the pull quote. Pictures are not brought across
--  (Rich is sorting them): real-data/legacy/news-pictures.csv says which article had which picture.
--  None is "featured", so the News page and the banner keep showing the newest articles.
--  Nothing already on the website is changed. All one transaction.
-- ─────────────────────────────────────────────────────────────
begin;

do $$ begin
  if exists (select 1 from articles where slug in ('haven-no-holiday-for-bethel', 'hawkins-storms-to-players-title', 'hawkins-claims-guild-hall-glory', 'heroes-and-villains-for-mevagissey', 'higgins-prince-of-wales')) then
    raise exception 'This part of the old news is already in: nothing to do.';
  end if;
end $$;

insert into categories (name, sort)
  select r.name, 100 + row_number() over (order by r.name) from (values
  ('Competitions'),
  ('Cue View'),
  ('League Meetings'),
  ('League News'),
  ('Match Reports'),
  ('Professional Snooker'),
  ('Snooker Memories')) r(name)
  where not exists (select 1 from categories c where lower(c.name) = lower(r.name));

create temp table _news (title text, slug text, category text, more_categories jsonb, excerpt text, lead text, quote_text text, body text, published_at date, is_published boolean, author text) on commit drop;
insert into _news values
  ('Haven no holiday for Bethel', 'haven-no-holiday-for-bethel', 'Match Reports', '[]'::jsonb, 'There was a major upset in the Rees Memorial League this week as previously unbeaten Bethel ‘B’ travelled to winless Gorran Haven but were soundly beaten 4-1 as the Haven moved off bottom spot. Shaun Hicks was…', null, '"It took a composed display by Howard Brett to edge out Jake ‘The Scarecrow’ Moore to gain Bethel ‘C’s second point at home to Bugle ‘C’ who know will surely climb the table."', 'There was a major upset in the Rees Memorial League this week as previously unbeaten Bethel ‘B’ travelled to winless Gorran Haven but were soundly beaten 4-1 as the Haven moved off bottom spot. Shaun Hicks was Bethel’s only winner.

more Lerryn have dropped to the bottom as Nathan Shaw edged out Terry Middleton giving Mevagissey ‘C’ a welcome win. Mevagissey ‘D’ produced a great 3-2 home win over Tywardreath ‘B’, Rob Blamey edging out Graham Kent in the evening. It took a composed display by Howard Brett to edge out Jake ‘The Scarecrow’ Moore to gain Bethel ‘C’s second point at home to Bugle ‘C’ who know will surely climb the table. There were some big winners in the Victory League as Tywadreath ‘A’ and Bugle ‘A’ both claimed maximum points with St Neot and Tregonissey both pitting four but Bugle’s lead is sure to be cut as they have their bye next week. Andrew Best’s 61, Gary Spencer’s 37 and Ian Powell’s 30 helped account for Sparks while Steve Court’s 33 and Farrant’s 38 kept St Neot in touch at the top then defeating Lostwithiel ‘B’ with both players scoring over 100 points in the frames. Bethel ‘A’ put a dent in Lostwithiel ‘A’’s title ambitions as G Stephens, Collard and Hawken moved the home side up to sixth place.

FULL RESULTS

Victory League: Bugle ‘A’ 5 (P Sturtridge, A Best (61), G Spencer (37), A Peers, I Powell (30)) Sparks 0; Lostwithiel ‘B’ 1 (L Flower) St Neot 4 (T Farrant (38), S Courts (33), A Courts, M Rowe); Tywardreath ‘A’ 5 (M Hancock, P Baron, A Gooch, D Kirwan, L Sturtridge), Mevagissey ‘B’; Tregonissey 4 (B McIntosh, C Kendall, R Bison, M Fox) Bugle ‘B’ 1 (G Taylor); Bethel ‘A’ 3 (G Stephens, L Collard, G Hawken) Lostwithiel ‘A’ 2 (C Dickinson, D Lock). Rees Memorial League: Mevagissey ‘D’ 3 (R Blamey, S Mills, N Parker) Tywardreath ‘B’ 2 (N Rowe, A Dennis); Gorran Haven 4 (L McKinstry, R Holmes, R Bunney, P Grimmett) Bethel ‘B’ 1 (S Hicks); Lerryn 2 (G Hoskin, G Brimicombe) Mevagissey ‘C’ 3 (B Prynn, M Chesterfield, N Shaw); Bethel ‘C’ 2 (J Cocks, H Brett) Bugle ‘C’ 3 (K Spencer, K Moore, N Couchman). Top breaks of the week: Andrew Best 61, Ryan Bilson 42, Gary Spencer 37, T Farrant 38, Steve Courts 33, Ian Powell 30, Barrie McIntosh 30, Ian Ball 30. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Hawkins Storms To Players Title', 'hawkins-storms-to-players-title', 'Professional Snooker', '[]'::jsonb, 'Barry Hawkins won the second ranking title of his career with a 4-0 victory over Gerard Greene in the Wyldecrest Parks Players Championship Grand Final.', null, '"I have played well against some very good players and come through a strong field," said Hawkins, who flies to Beijing tomorrow as he plays his first match in the China Open in Tuesday. "I rode my luck during the week because I could have lost to Ryan Day, he missed the brown in the last frame. But overall I think I deserved to win. It was a big occasion with big money so I''m delighted to win."', 'Barry Hawkins won the second ranking title of his career with a 4-0 victory over Gerard Greene in the Wyldecrest Parks Players Championship Grand Final.

more Hawkins dominated a one-sided final against the tournament''s surprise package, world number 66 Greene. Against his friend and practice partner, world number five Hawkins showed no mercy as he cruised to the bumper £100,000 top prize at the Guild Hall in Preston. With a rock solid all-round game and composed demeanour at the table, Kent-based 34-year-old Hawkins has shown dramatic improvement over the past two years, winning his first ranking title at the 2012 Australian Goldfields Open and now doubling his tally. He also won the Shoot-Out in 2012 and was runner-up to Ronnie O''Sullivan at the World Championship last season. He will certainly be a threat again at the Crucible next month. The tournament in Preston was the culmination of a series of events around Europe and in China which have run throughout the season. In fact Hawkins was grateful even to be among the line-up, as he finished 25th on the European Tour Order of Merit with only the top 24 due to qualify. But Stuart Bingham''s victory in the last Asian Tour event meant that he qualified from that list, allowing one extra player from the European list a spot at the Guild Hall. And Hawkins took full advantage with a series of fine displays. He was particularly impressive in a 4-1 defeat of Judd Trump in the semi-finals earlier today, and continued in the same vein against Greene. Breaks of 117 and 75 put him 2-0 up within 20 minutes, his opponent failing to register a point. Greene got his first scoring chance in frame three and made 34, but later missed a tricky black at 35-1. The Hawk swooped with a 50 clearance for 3-0. Runs of 22 and 30 put him ahead in frame four, and though he missed a simple red to a centre pocket, he soon got another chance as Greene''s attempted red to a baulk corner finished in the jaws. Hawkins added enough points to make sure of the title. "I have played well against some very good players and come through a strong field," said Hawkins, who flies to Beijing tomorrow as he plays his first match in the China Open in Tuesday. "I rode my luck during the week because I could have lost to Ryan Day, he missed the brown in the last frame. But overall I think I deserved to win. It was a big occasion with big money so I''m delighted to win. I''m getting to the later stages of tournaments more often now and when you do that, eventually the door will open for you." Greene enjoyed the best week of his 21-year career so far, reaching his first ranking final and collecting his biggest cheque - £38,000. Having slipped down the rankings in recent years, he feared for his tour place at the start of the current season. A run to the final of the Paul Hunter Classic European Tour event last August allayed that fear and booked him a place in Preston, and his run this week is a huge boost to his confidence and bank balance. "There have been some tough times over the last few years," said the 40-year-old Rainham-based cueman. "I always felt I was good enough to do well but I seem to bring the best out of other players. Consistency and confidence have been lacking. This has been a great week and I''m looking forward to the World Championship qualifiers now. I''m just disappointed with how I played in the final. I didn''t get a shot for the first two frames and then I missed the black in the third when I could have got back to 2-1." Article courtesy of the World Snooker Images Courtesy of: Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('Hawkins claims Guild Hall glory', 'hawkins-claims-guild-hall-glory', 'Match Reports', '[]'::jsonb, 'Barry Hawkins produced irresistible snooker to claim the Ladbrokes World Grand Prix title in Preston, but he had to withstand a heroic fightback from Ryan Day, eventually winning 10-7.', null, '“If I had lost that last frame there I don’t know what would have happened. I just managed to hold myself together and I got a lucky kiss on the blue after potting the brown. You can miss absolutely anything under that kind of pressure. I’m so delighted to win another tournament. I feel like I’ve been knocking on the door for a little while. I’ve had a few disappointments on the way so I think I deserved that one.”', 'Barry Hawkins produced irresistible snooker to claim the Ladbrokes World Grand Prix title in Preston, but he had to withstand a heroic fightback from Ryan Day, eventually winning 10-7.

more It’s a third ranking title for Hawkins, which brings him level with the likes of Mark Allen, James Wattana and Paul Hunter. Two of the Hawk’s wins have now come at the historic Guild Hall in Preston. He was victorious at the Lancashire venue in 2014, when he picked up the Players Championship Grand Final crown, beating Gerard Greene 4-0 in the final. Day was seeking to become the fifth maiden ranking title winner of the season, having spent 18 years as a professional seeking silverware. He was faced with an opponent playing some of the snooker of his life in the opening session, but provided stout resistance to keep the deficit to 6-3. Hawkins made a phenomenal five centuries, including four in the first session. He added runs of 128 and 85 at the start of the evening, as he moved 9-3 ahead and looked set for a short evening’s work. It was a remarkable burst which got him to the verge of victory, the 37-year-old scoring 315 unanswered points. Hawkins had two gilt edged chances at the start of frame 13. He spurned straightforward reds and opened the window for the Welshman. Day ironically punched the air after potting an opening red following the onslaught. He went on to keep his hopes alive with breaks of 21 and 87. The four-time ranking finalist showed incredible resolve by making breaks of 84, 92 and 75 to turn up the heat on the Hawk and close the gap to 9-7. Day looked like he was going to pile even more tension on the Englishman, who let a 5-1 semi-final lead slip against Joe Perry in last month’s masters, when he led by 31 points in the 17th frame. Eventually Hawkins laid his opponent in a perilous snooker, which afforded him his chance. Hawkins cleared the table and dramatically clinched the title and the £100,000 top prize. “I’m absolutely over the moon. I felt so good at the start of the match and played so well. I didn’t feel like I could miss when I got in the balls,” said Hawkins. “I got ahead of myself thinking I was going to make another century to win.” “If I had lost that last frame there I don’t know what would have happened. I just managed to hold myself together and I got a lucky kiss on the blue after potting the brown. You can miss absolutely anything under that kind of pressure. I’m so delighted to win another tournament. I feel like I’ve been knocking on the door for a little while. I’ve had a few disappointments on the way so I think I deserved that one.” Day said: “Every half mistake I had early on, he made a century break. That ramps the pressure up on your next visit, whether it’s a chance in the balls or a safety shot. He was relentless. “If I had won the seventeenth frame, I think it was game on as Barry was starting to feel the pressure. I won four frames relatively quickly. I beat Alfie Burden from 9-5 down in World Championship qualifying last year so I was trying to draw on that.” “I’m disappointed, but I’m happy with the week. I would have taken being a finalist at the start of the week. Sometimes you just have to tip your hat and say well done.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Heroes and Villains for Mevagissey', 'heroes-and-villains-for-mevagissey', 'Match Reports', '[]'::jsonb, 'The Meva B heroes returned from Lostwithiel A with a great 3-2 win, but that win was reversed at Meva A, as Lostwithiel B Triumphed 3-2.', null, '"But Andrew Best restored parity with a great 72 break before the A team grabbed the last 3 frames to keep 2 points clear."', 'The Meva B heroes returned from Lostwithiel A with a great 3-2 win, but that win was reversed at Meva A, as Lostwithiel B Triumphed 3-2.

more Veteran Leighton Varcoes made a break of 33 against George Lory, during the standout frame of the evening. It’s ‘as you were’ at the top of the league as the top threee all recoreded 4-1 victories. Paul Baron had a 31 and Andrew Gooch, a 32 at Bethel Q, but Goochy was brushed aside by a dominant Leon Collard to record Bethel’s only success. Another player to have a good break and lose was Chris Kendall, who was edged out by Clive Sturtridge as Treggey beat Bodmin Sparks. Barry McIntosh’s 44 and Chris Stephenson’s 39 for the winners. The Bugle Derby was eventful as Ian Ball thrashed Ian Powell by 59 points to 1 in the first frame of the evening. But Andrew Best restored parity with a great 72 break before the A team grabbed the last 3 frames to keep 2 points clear. Leaders of the Rees League, St Blazey continued their relentless surge for the title, beating Lerryn 5-0, but only 3 points separate the five teams below them in the chase for the second spot. Bugle C faired best this week beating Gorran Haven 4-1 with Lee McKinstry again on the mark for Gorran whilst Tywardreath B continued to pick up regular points after seeing off Bethel D 3-2 and in the Bethel Derby, Roger Smithson saw off Ben Stunell in the decider for the C team’s 3-2 victory of the B team.

FULL RESULTS

Victory League: Mevagissey ''A'' 2 (L Varcoe (33), P Staley) Lostwithiel ''B'' 3 (B Warne, L Flower, J Daniells), Bugle ''B'' 1 (I Ball) Bugle ''A'' 4 (A Best (72), A Peers, P Strurtridge, G Spencer), Tregonissey 4 (R Bilson, B McInstosh (44), C Stephenson (39), R Pearson – not scoring C Kendall (32)) Sparks 1 (C Strutridge), Lostwithiel ''A'' 2 (C Perring, D Lock (33)) Mevagissey ''B'' 3 (D Kendall, M Gregory, M Mills), Bethel ''A'' 1 (L Collard) Tywardreath ''A'' 4 (P Baron, D Kirwan, L Sturtridge, M Hancock). Rees Memorial League: Bugle ''C'' 4 (J Moore, K Spencer, N Couchman, K Moore) Gorran Haven 1 (L McKinstry), Tywardreath ''B'' 3 (K Wilks, P Hunt, A Dennis) Bethel ''D'' 2 (T Stephen, V Hathway), Bethel ''C'' 3 (S Jones, J Cocks, R Smithson) Bethel ''B'' 2 (M Green, S Hicks), St Blazey 5 (M Mears, L Rosevear, L Reynolds, S Dewings, M Woodward (34)). Top breaks of the week: Andrew Gooch 32, Leighton Varcoe 33, Paul Baron 31, Chris Stephenson 39, Barrie McIntosh 44, Andrew Best 72. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Higgins - Prince Of Wales', 'higgins-prince-of-wales', 'Professional Snooker', '[]'::jsonb, 'John Higgins won the BetVictor Welsh Open for a record fourth time by beating Ben Woollaston 9-3 in a one-sided final in Cardiff.', null, '""The doubts over the past couple of years were really deep. I was thinking far too much and not putting enough work in. I was trying different things with my technique instead of just going back to basics and potting balls. It was snow-balling and I was just scratching, trying to find something. Over the last couple of months it has felt better, so to be here this week and to feel as if my game is back and my technique is there is brilliant."', 'John Higgins won the BetVictor Welsh Open for a record fourth time by beating Ben Woollaston 9-3 in a one-sided final in Cardiff.

more Higgins has won an array of trophies over his glittering career but this one will mean more to him than most, as he had not captured a ranking title since the 2012 Shanghai Masters, 29 months ago, and had spells when he wondered whether he would ever taste such success again. But after showing signs of vintage form throughout a seven-match winning streak this week at the Motorpoint Arena, Higgins has improved his career tally of ranking titles to 26, just behind Ronnie O''Sullivan (27) and Steve Davis (28) - though Stephen Hendry''s record of 36 is surely out of range. Wizard of Wishaw Higgins can at least claim one record ahead of Hendry and O''Sullivan, as the trio had previously been tied on three Welsh Open titles apiece. He also goes back to Scotland with the £60,000 top prize after out-playing underdog Woollaston in the final. In fact the contest was close in the early stages, but Higgins won a crucial final frame of the opening session and never looked back. Undoubtedly one of snooker''s all-time greats, Higgins is aged 39 and feared over the past two years that his best days were behind him. He has had to take a back seat while O''Sullivan - born in the same year - has shown arguably the best form of his career, while younger guns like Mark Selby, Neil Robertson and Ding Junhui have shared most of the trophies. Higgins even looked in danger of dropping out of the top 16 before this week, but has surely now secured his place among the elite for the rest of the season, and if he maintains his current standard he will going into the World Championship with high hopes of matching O''Sullivan''s tally of five Crucible crowns. Woollaston has enjoyed the best week of his snooker career as he had never previously been beyond the quarter-finals of a ranking event. The 27-year-old from Leicester claimed some major scalps on his way to the final, including Mark Allen, Ali Carter and Mark Williams, and has shown that he has the potential to succeed at the top level. The world number 36, whose only professional title came at a Players Tour Championship event in 2011, will enjoy his biggest pay-day of £30,000. Higgins led 5-3 after the first session and soon extended his lead tonight, dominating the opening frame with a top break of 46. The next was a scrappy affair lasting 29 minutes and it came down to the last red. Higgins, leading 46-34, laid a clever snooker on the red, and although Woollaston hit it, he left his opponent the chance to clear for 7-3. That ended Woollaston''s resistance as Higgins sailed through the last two frames with top breaks of 68 and 83. "In the last two years I didn''t think it could happen again," said Higgins, who was joined in the arena by wife Denise and eldest son Pierce as he celebrated with the trophy. "I''m delighted. Nothing went right for Ben today. The biggest frame of the match was the eighth when I fluked the green. If it had been 4-4 it might have been different tonight. "Ben has had some great wins this week, and because I haven''t been playing that well I knew I could fall at any hurdle. He has been playing at a very high level all week. So that kept my feet on the ground right up until potting the winning ball. I was just trying to stay focussed and not give him any easy chances. "Overall I''ve played some good matches this week, and when I haven''t played well I have dug in and kept going. To be sitting here with a trophy is a great feeling. This gives me a lot of confidence that I can compete with the top players. "The doubts over the past couple of years were really deep. I was thinking far too much and not putting enough work in. I was trying different things with my technique instead of just going back to basics and potting balls. It was snow-balling and I was just scratching, trying to find something. Over the last couple of months it has felt better, so to be here this week and to feel as if my game is back and my technique is there is brilliant. "I have to say thanks to Raymond Cohen from Exquisite Cues in Scotland. He has made me a few cues over the past couple of years and I was chopping and changing. But he managed to make one at the start of this year which was just like my old cue in terms of the weight, length and thickness of butt. When I was tinkering about he''d get a sore head and crack up at me. He wanted to help me and he knew I shouldn''t have been tinkering that much." Woollaston said: "It has been an amazing week. I''m disappointed about the final, but in an hour or two I''ll realise what I have achieved. Hopefully this will give me the confidence to get to more finals. I''ve had some big wins this week and played some good snooker. The money is a massive help to me. "The eighth frame was important. John fluked the green but I should have won the frame before that by making a big break. Tonight I missed a few balls and when I got a chance, everything seemed to go wrong. John got away with a few shots all day. But his safety was so good, a lot of the time I didn''t know what to do. I''ve always believed I belong with these players, but maybe not in the TV stages of ranking events - until now." Article courtesy of the World Snooker Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('Higgins Wins Championship League', 'higgins-wins-championship-league', 'Professional Snooker', '[]'::jsonb, 'John Higgins is the 2017 Championship League Snooker winner as he defeated Ryan Day 3-0 in the final match of a long week at the Ricoh Arena in Coventry. It was the scene of Higgins’ Champion of Champions victory…', null, '“Ryan was unlucky with a couple of kicks in the final frame but I was really happy how I played in the semi and the final, it was probably the best I have played all week.', 'John Higgins is the 2017 Championship League Snooker winner as he defeated Ryan Day 3-0 in the final match of a long week at the Ricoh Arena in Coventry. It was the scene of Higgins’ Champion of Champions victory back in November and it is proving to be a happy hunting ground for the Scottish veteran.

more “I love Coventry!” he said. “It is good to win Champion of Champions, win my group and then win the Championship League. I am looking forward to coming back for the Champion of Champions later in the year to try to defend that title.” Higgins, who started the competition earlier in the week in Group Seven, took a first prize of £10,000 as well £300 per frame won in the semis and final and £200 per frame in the group stages. His total tally of £20,900 was a fair reward for four days graft. By reaching the final Day enjoyed the most lucrative season in the ten year history of the Championship League. He won a total £32,600 which overtook Martin Gould’s £31,117 which he achieved in his winning year of 2013. Earlier, Higgins had defeated Judd Trump in the semi-finals while Day had got the better of Barry Hawkins. Higgins added: “Ryan was unlucky with a couple of kicks in the final frame but I was really happy how I played in the semi and the final, it was probably the best I have played all week. “I was delighted to play like that this week. Any win is a great win, it doesn’t matter it if is the Championship League or the World Championship – I was struggling with confidence and winning a trophy gives you confidence. I have lost three first-round games recently so to come here and win is pleasing. It is great match practice and hopefully I can take that forward and do well in the last three or four big tournaments we have left and cap off a great season I have had.” In the Group Stages Mark Davis became the first man in snooker history to make two maximum breaks in the same tournament. The East Sussex man compiled a 147 against Neil Robertson back in January – the first of his lengthy career. He then followed that up today against John Higgins to double his maximum tally. It was the 11th max of this season, the 129th in snooker history and he broke his own record as the oldest player to make a 147 (44 yrs 202 days). Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Higgins equals Davis tally', 'higgins-equals-davis-tally', 'Professional Snooker', '[]'::jsonb, 'John Higgins won the 28th ranking title of his career – matching the tally of Steve Davis – by beating David Gilbert 10-5 in the final of the International Championship in Daqing, China.', null, '“It’s a special moment for me to get to 28 ranking titles,” said Higgins, who turned pro in 1992. “Steve Davis was my hero growing up and back then I would never have dreamed I could equal any of his records. It’s a moment I will never forget. Stephen Hendry is still well out in front and maybe I won’t get to 36, but you never know. I’ve won three this year so if I keep doing that it will only take me three more years. I love snooker and I don’t think I’ll ever retire.', 'John Higgins won the 28th ranking title of his career – matching the tally of Steve Davis – by beating David Gilbert 10-5 in the final of the International Championship in Daqing, China.

more Higgins pulled away from 4-4 to win six of the last seven frames to win the £125,000 top prize, snooker’s biggest cheque on offer outside the UK and the Scot’s biggest since he won his fourth world title in 2011. Wishaw’s 40-year-old Higgins now stands level with his boyhood idol Davis on 28 ranking crowns, one ahead of Ronnie O’Sullivan though still eight behind Stephen Hendry’s seemingly impregnable record of 36. In fact Higgins endured a 29-month drought without a ranking title after winning the 2012 Shanghai Masters, but has returned to form in emphatic fashion this year. He captured the Welsh Open in February and the Australian Goldfields Open at the start of the current season in July, and has now emerged victorious from a tournament he described himself this week as the second biggest on the calendar. The world number 12 won seven matches in all during the event, highlighted by a 6-0 thumping of Shaun Murphy, a 9-4 defeat of world number one Mark Selby and today’s win over Gilbert in a high quality final. Tamworth’s 34-year-old Gilbert, the world number 40, had never previous been beyond the last 16 of a full ranking event but played the best snooker of his career this week. There was no fairytale ending for the former potato farmer, but a cheque for £65,000 and a leap up the world ranking list are welcome consolations. He continued in the same vein as the evening session got underway as breaks of 129 and 88 extended his lead to 7-4. Gilbert pulled one back with a 51 and looked set to win frame 13 until he broke down on 54. Higgins made a vital 88 clearance to lead 8-5 at the interval. And he soon closed out victory, helped by runs of 52 and 56 in the next two frames. Gilbert settled quickly into the final and led 2-1 after a break of 100 in the third frame. Higgins took the next two with 66 and 69 then stole the sixth on the colours to lead 4-2. Gilbert fought back impressively with 77 and 59 to square the match, though it was Higgins who won the last of the afternoon session with a run of 108 to lead 5-4. “It’s a special moment for me to get to 28 ranking titles,” said Higgins, who turned pro in 1992. “Steve Davis was my hero growing up and back then I would never have dreamed I could equal any of his records. It’s a moment I will never forget. Stephen Hendry is still well out in front and maybe I won’t get to 36, but you never know. I’ve won three this year so if I keep doing that it will only take me three more years. I love snooker and I don’t think I’ll ever retire. “I think this has been the best I have ever played continually throughout a whole tournament. I only played one bad mini-session against Michael Holt. The way I played against Murphy and Selby – I can’t play much better than that. “Today was David’s first final and he should be proud of himself because he played some great frames. It was a closer match than 10-5 suggests. He’s got a taste for it now and hopefully he’ll have many more finals. “I’ve had spells in my career where I have not won a tournament for three or four years, then I’ve had bursts where I have won a few. I’m very pleased to have won three this year, it’s a great achievement given how many great players are out there. “My next goal is to win another world title. If I can produce that sort of form I’ll have a good chance at Sheffield.” “It feels strange to say I’m disappointed to lose in a final because I’ve never got close to one before. I had my chances but I missed a few, and John kept clearing up. It was in the back of my mind not to miss because I knew he’d always punish me, and sometimes the harder you try, the harder the game gets. “At least I’m going home with £65,000, which is more money than I’ve ever seen. My wife moved into our new house this week so I’m sure she’s already ordering new carpets and furniture. “I just want to say thank you to the people of Daqing for being so kind to me, it has been a great event and the conditions have been superb. It was a great atmosphere tonight and I hope we come back next year.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Higgins is Champion of Champions', 'higgins-is-champion-of-champions', 'Professional Snooker', '[]'::jsonb, 'John Higgins won his second consecutive title by beating Ronnie O’Sullivan 10-7 in the final of the Dafabet Champion of Champions in Coventry.', null, '“I thought I had missed the boat at 5-4, he missed a couple but I never took advantage. I was thinking, is that going to give him confidence and then he will go on a roll? I stuck with it and felt great coming into tonight.', 'John Higgins won his second consecutive title by beating Ronnie O’Sullivan 10-7 in the final of the Dafabet Champion of Champions in Coventry.

more The Scotsman took the £100,000 top prize, making it a highly lucrative fortnight following a £200,000 winner’s cheque at another inivtation tournament – the Evergrande China Championship – last week. It was O’Sullivan’s first defeat in the four year history of the Dafabet Champion of Champions – he was a winner of the event in 2013 and ’14 and didn’t compete last year. The Englishman was leading 5-4 after the afternoon session, but Higgins got the better of the evening exchanges, levelling the match at 7-7 and then pulling away with three frame winning breaks to take victory. The afternoon session saw eight of the nine frames decided by breaks over 60. Following the restart in the evening Higgins seized the initiative as breaks of 60 and 63 saw him take the lead at 6-5. O’Sullivan levelled with a 74 before Higgins regained his lead at 7-6 with a run of 83. The Rocket though, produced a magnificent run of 130 – the highest of the match – to once again leave the match finely poised at 7-7. But O’Sullivan scored just one point in the next three frames as Higgins swept to victory with runs of 76, 86, 40 and 58. “I am delighted to put my name on the list of Champion of Champions winners,” said Higgins. “It has been a good two weeks and you have to roll with it when it is going for you. “I can’t speak for Ronnie but I was buzzed up coming into play. I just wish my old man was still here to see me take part in these finals,” Higgins added, referring to his father John who passed away in 2011. “I thought I had missed the boat at 5-4, he missed a couple but I never took advantage. I was thinking, is that going to give him confidence and then he will go on a roll? I stuck with it and felt great coming into tonight. “When I play like that, there is no greater feeling. You get in the balls and think you are going to clear up at every chance. I missed a couple at the end but potted a good long red to swing it back my way and finish it off. There is no better feeling than doing it in front of a packed audience, playing against somebody as good as Ronnie.” O’Sullivan, still seeking his first title of the season, was gracious in defeat. He said: “Well played to John, he played fantastic all week – he was by far the best player of the week. I tried to hang on in there today and make a game of it. John is on a roll at the minute, he is really starting to play as he did a few years ago, so for me he is probably the best player in the world at the moment with the way he is playing. “I need to find some consistency if I am going to win tournaments again. It is ok playing in spells but you get found out playing players like John. Against most players I might have had a chance of winning but against world-class opposition I made too many mistakes.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Higgins is Guangzhou king', 'higgins-is-guangzhou-king', 'Professional Snooker', '[]'::jsonb, 'John Higgins beat Stuart Bingham 10-7 in the final of the new Evergrande China Championship to bank £200,000, snooker’s biggest ever first prize for a tournament outside the UK.', null, '“Time stands still for no one so all you can do is try to fight back as much as you can. This gives me great confidence because I don’t think I’ve ever finished a final like that, so it proves to me that I can still do it under extreme pressure. I’m really chuffed to bits.', 'John Higgins beat Stuart Bingham 10-7 in the final of the new Evergrande China Championship to bank £200,000, snooker’s biggest ever first prize for a tournament outside the UK.

more A stunning finish of three centuries in the last three frames gave Higgins his biggest pay-day since capturing his fourth world title in 2011. Scotland’s 41-year-old Higgins won his first trophy since last year’s International Championship, though this invitation title does not count towards his tally of 28 ranking crowns. The world number six from Wishaw won four matches in Guangzhou, culminating in a superb display in a high quality final against Bingham which featured five centuries and nine more breaks over 50 in the 17 frames. The contest started slowly, Higgins getting the better of the first three scrappy frames, before Bingham stormed back with runs of 102, 112 and 52 to make it 3-3. Higgins regained the lead in frame seven then made a trademark clearance of 65 to go 5-3 up, before two breaks of 50 from Bingham saw him trail by just one frame at the end of the first session. Basildon’s Bingham, who was seeking his first title since winning the World Championship 18 months ago, won the opening frame of the evening session then made a break of 98 in the next to lead for the first time at 6-5. Higgins responded with 56 and 65 to win the next two, before Bingham’s 84 left the match in the balance at 7-7. But Higgins once again underlined his status as one of snooker’s all-time greats with a stunning finish, firing runs of 134, 100 and 101 to cross the winning post. “At 7-7 I was just hanging in there, Stuart was playing the better stuff and I was just scrapping away,” said Higgins. “I knew my form needed to come. It’s a dream come true to finish a match off like that with three centuries, especially for such a big prize and a big tournament. I’m definitely taking this trophy home! “In recent matches I have sometimes been guilty of not having the correct mindset, but I was really zoned in tonight. Even when I went 6-5 down I stayed positive and kept concentrating on every ball. “Time stands still for no one so all you can do is try to fight back as much as you can. This gives me great confidence because I don’t think I’ve ever finished a final like that, so it proves to me that I can still do it under extreme pressure. I’m really chuffed to bits. “This is the first time I have been to Guangzhou, it’s a great city and I have really enjoyed it. I’m sure all the players will love coming here next year. Big thanks to Evergrande because they have put on a big tournament with a fantastic prize fund, it’s out of this world. Hopefully they’ve had good feedback this week from the players. The fans were brilliant, it was a great atmosphere tonight and hopefully this can build into a massive tournament.” World number two Bingham, who earned £100,000, said: “It was a great match and he finished in style. I had a couple of chances to go 8-8 but I didn’t do much wrong and I was glad to be part of it. John is still a class act and a match for anyone. I feel as if my game is there and I felt comfortable out there.” For the next three years, the Evergrande China Championship will be a world ranking event, contested by 128 players. Total prize money for the 2017 edition will be £700,000 with the winner’s cheque at £150,000. Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Higgins on top down under', 'higgins-on-top-down-under', 'Professional Snooker', '[]'::jsonb, 'John Higgins won the 27th ranking title of his career by beating Martin Gould 9-8 in an exciting final at the Australian Goldfields Open in Bendigo.', null, 'It would be dream material if I could get to 28 ranking titles and equal Steve Davis. Ronnie O’Sullivan has won more than me over the years, made more century breaks and won more world titles. So he’s in front and he’s chasing Stephen Hendry’s records. I don’t know how long I’ll be able to keep going and trying to win tournaments, I’m just really happy to have won this one.', 'John Higgins won the 27th ranking title of his career by beating Martin Gould 9-8 in an exciting final at the Australian Goldfields Open in Bendigo.

more Gould, who had been seeking his first ranking title, fought back from 7-5 and 8-7 down to 8-8, but a superb break of 89 from Higgins proved decisive in the last frame. It’s the perfect start to the season for Scotland’s 40-year-old Higgins as he takes the A$75,000 top prize in the first ranking event of the campaign. Victory brings his career tally level with Ronnie O’Sullivan and just one behind Steve Davis, though still nine short of Stephen Hendry’s record 36 ranking crowns. Four-time World Champion Higgins suffered a long lean spell of over two years before winning the Welsh Open last February, signalling his return to form. Playing alongside Stephen Maguire, he also reached the final of the World Cup last month before losing to China B. Carrying that form and match sharpness into the event in Australia, he won five matches, culminating in today’s win over Londoner Gould. World number 26 Gould heads home with a cheque for A$32,000. World number 13 Higgins won the opening frame with a break of 90 then took the second with a 30 clearance. Gould stormed back by winning four frames in a row with top runs of 101, 86 and 89. Higgins took the next with a 112 and added the eighth to leave them tied at 4-4 after the first session. Wishaw’s Higgins went 6-4 ahead at the start of the evening session. Gould pulled one back with a superb 138 and he led 40-0 in the next, only for his opponent to clear with 66 to make it 7-5 at the interval. Gould fought back to take the next two with top runs of 55 and 58 to level at 7-7, and he had chances in the next but it was Higgins who won it with a break of 60. Higgins could have clinched victory in frame 16 but missed a tricky last red when leading 54-33, and Gould cleared for 8-8. Gould had first chance in the decider but could only make 8, and Higgins, as he has done so often, rose to the occasion with his match-winning 89. “It was one of the best finals I’ve ever been involved in,” said Higgins. “Credit to Martin because it was a brilliant match, I’m sure he’ll start winning tournaments now. The crowds have been fantastic all week and the players really appreciate that. “I wasn’t feeling any nerves at the end. I missed the chance to win 9-7 and he made a great break for 8-8. It was anyone’s game and I managed to hold myself together in the last frame, so I’m delighted. “I made a little technical change before the World Cup, standing more square-on to the shot, whereas before I felt my right leg was leading off into areas it shouldn’t be going. It seems to be working. “This gives me confidence to go on and do well this season. I’ve got a few weeks off now to go away on holiday with the family.” Gould said: “I can’t say I’m not gutted, but I’ll be back again. It was a high quality match today with a lot of big breaks. The support I have had here has been unbelievable. Hopefully they won’t get too upset when we beat them in the cricket! “I’d like to dedicate this week to my sister. Just before I came out here her dad passed away. This one is for her.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Higgins wins record fifth Welsh Open', 'higgins-wins-record-fifth-welsh-open', 'Professional Snooker', '[]'::jsonb, 'John Higgins beat Barry Hawkins 9-7 in the final of the ManBetX Welsh Open, becoming the first player to win the title five times.', null, '“I’m over the moon, it will sink in over the next couple of days. To get to 30 ranking titles is beyond my wildest dreams. Who knows how many more I can win but I have managed to win two this season.', 'John Higgins beat Barry Hawkins 9-7 in the final of the ManBetX Welsh Open, becoming the first player to win the title five times.

more Higgins came from 4-2 down to win seven of the last ten frames of a high quality final in Cardiff to take the Ray Reardon Trophy and a top prize of £70,000. The Welsh Open is snooker’s longest running ranking event other than the World and UK Championships, and Higgins now goes one ahead of Ronnie O’Sullivan with five crowns, having previously triumphed in 2000, 2010, 2011 and 2015. Scotland’s Higgins captured his second ranking title of the season, having won the Indian Open in September, and 30th of his career. That leaves him just two behind O’Sullivan on the all time list and six behind Stephen Hendry. At the age of 42, Higgins remains one of the fiercest competitors on the tour, and his renowned all-round game is as strong as ever. The trio of greats who turned pro in 1992 – Higgins, O’Sullivan and Mark Williams – have now won eight of this season’s 16 ranking events between them. All three play with the demeanour of men who have achieved plenty in their careers and are now enjoying what is left, without the pressure that usually comes with intense competition at the top level. Higgins remains at number five in the world rankings but closes the gap on fourth-placed Ding Junhui. Hawkins, who moves up one place to seventh thanks to his £30,000 runner-up prize, missed the chance to win a fourth ranking title and first since the World Grand Prix a year ago. This season has been a tough one for the 38-year-old Londoner on and off the table as he has had to come to terms with the tragic death of his brother in law. As he explained after his semi-final match yesterday, only in recent weeks has he been able to focus on snooker. A welcome return to form in Cardiff will give the former Crucible finalist confidence for the rest of the season. However he misses out on a place in the Players Championship in Llandudno later this month – only the top prize tonight would have jumped him into the top 16 of the one-year ranking list. Tied at 4-4 after the first session, Higgins took the opening frame tonight, then came from 44-10 behind in the next to win it with a 49 clearance, going 6-4 ahead. Hawkins hit back superbly with back to back centuries, 103 and 138, to level at the interval. In frame 13, Hawkins had what looked like a handy 44-4 lead with several reds close to the top cushion, only for Higgins to make a trademark 66 clearance to regain the lead. The 14th came down to a safety battle on the last red and Hawkins, trailing 59-38, converted a cracking long pot to set up a chance to clear, and he got to the pink before missing a tricky pot to a baulk corner. After a brief tactical exchange, Higgins knocked in the pink to lead 8-6. Back came Hawkins with a break of 82 to draw within one frame. But the Englishman botched a safety early in frame 16, letting Higgins in for a break of 64 which ended when he missed a tough red to a baulk corner. Hawkins had one more chance but missed a red to centre, and Higgins added the points he needed to win a Home Nations tournament for the first time. “That was one of the most enjoyable finals I have played in and it’s fantastic to win,” said four-time World Champion Higgins. “There were a couple of really tight frames towards the end. Barry will be kicking himself that he didn’t go 7-6 up or win the next frame to go 7-7. It seemed destined to go to a decider and the match probably deserved that. But I made a good break in the last frame. “I’m over the moon, it will sink in over the next couple of days. To get to 30 ranking titles is beyond my wildest dreams. Who knows how many more I can win but I have managed to win two this season. “After losing the World Championship final last season (to Mark Selby) I got a bit down on myself in private moments, thinking it was a great chance to win. But now I have proved I am still capable of winning events. I haven’t done that at the Masters, UK or World for seven years so that’s my goal now. “Walking out for the final session tonight at 6-6, there’s nothing to beat that. Your adrenaline is going, you’re nervous, short of breath and you want to be sick. There are a whole range of emotions. But when you’re actually down on the shot you’re enjoying it and loving the situation you are in. I can’t replicate that in anything else I do in my life. It’s like a drug, you want to try it again and again.” Hawkins, who has now lost three of his six ranking finals, said: “I am a bit gutted. I feel as if I played well but John was more clinical. I can’t beat myself up too much because John is one of the all-time greats and I pushed him all the way. I kept fighting and didn’t give up. “I had a chance to go 5-2 up in the first session and you have to take those sort of opportunities against John. I felt very good in spells and there are definitely positives to take from the week. I feel as if my game is in good shape.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('ITV4 To Broadcast Snooker''s World Open', 'itv4-to-broadcast-snookers-world-open', 'Professional Snooker', '[]'::jsonb, 'ITV4 is to show full coverage of snooker''s Haikou World Open, which begins next Monday.', null, '""The Haikou World Open is a superb event with a top prize of £85,000 and deserves to be brought to a wider audience with free to air broadcast in the UK. We are a rapidly growing global sport and there is a high demand among fans."', 'ITV4 is to show full coverage of snooker''s Haikou World Open, which begins next Monday.

more Extensive live coverage of the tournament in China begins on Monday 25 February, running from 6.10am to 3pm each day until the final on Sunday March 3. It marks a return to snooker for the ITV network, as the sport''s first ranking event shown since the 1993 British Open. The Haikou World Open, staged on Hainan Island, will feature star players, including China''s number one Ding Junhui, defending champion Mark Allen, world number one Judd Trump, John Higgins, Mark Selby and Neil Robertson. Clive Everton, Neal Foulds and Peter Drury will make up the commentary team for ITV4''s coverage. Niall Sloane, ITV Director of Sport, said: "We are delighted to bring to our viewers comprehensive coverage of such a key event in the snooker calendar, which adds another dimension to ITV4''s sports portfolio." World Snooker Chairman Barry Hearn said: "We are developing an increasingly competitive marketplace in terms of broadcast of our events so it''s a fantastic step forward for ITV to provide extensive live coverage of a world ranking event. We''re delighted to be working with the ITV team. "The Haikou World Open is a superb event with a top prize of £85,000 and deserves to be brought to a wider audience with free to air broadcast in the UK. We are a rapidly growing global sport and there is a high demand among fans." Article courtesy of the World Snooker Images Courtesy of: ITV', '2014-01-01', false, 'Richard Pearson'),
  ('Ian is on the ball for Bugle', 'ian-is-on-the-ball-for-bugle', 'Match Reports', '[]'::jsonb, 'Bugle ‘A’ dropped two points at Pelynt in an eventual night of snooker.', null, 'Richard Bolt and Guy Buckle put the visitors two up before Mike Hooley defeated Jim Tamblyn to give Treggy some hope but that was quickly dampened as Clive Stuthridge hammered Justin Hooley. Phil Hooley beat Martin Isted in the last to get the second home point.', 'Bugle ‘A’ dropped two points at Pelynt in an eventual night of snooker.

more It had started so well for them as Paul Sturtridge beat Lenny Flower and then Gary Spencer knocked in a fine 47 break only to lose to a 34 clearance by Phil Ormand. Andrew Best sneaked past Richard Broad in the next only for John Daniell to level things with Jake Moore potting the black only to go in off. Ian Ball secured a win knocked in a 37 when beating Will Courtis. Bethel ‘A’ moved up to second place courtesy of a 5-0 home win over St Stephen ‘A’ which was hard on the visitors who were well into three frames and deserved better with John Bennett and Dan Allen both losing on the black to Matt Green and Gary Stephens respectively. Also on target for the home team were Geoff Hawken, Leon Collard and Andy Peers. St Blazey ‘A’ produced an excellent performance at Bugle ‘B’ to win 5-0. Stewart Dewings, Nick Kendall, Aiden Maxwell-Craddock and dad Mark all won leaving captain Mickey Meares to shade a close one with Colin Rundle to secure the nap hand win. Tregonissey ‘A’ beat Mevagissey ‘B’ 4-1 to move into third place. Matt Woodward’s black-ball victory over Nathan Shaw got them underway but Mark Gregory levelled things hammering Ryan Bilson but further wins for Martin Knight, Jason Cocks and Barrie McIntosh gave them victory. The Runabout Shield is on the move after Bethel ‘B’ inflicted Tregonissey ‘B’s first defeat of the season. Richard Bolt and Guy Buckle put the visitors two up before Mike Hooley defeated Jim Tamblyn to give Treggy some hope but that was quickly dampened as Clive Stuthridge hammered Justin Hooley. Phil Hooley beat Martin Isted in the last to get the second home point. Mevagissey ‘C’ have jumped up to joint second after a 5-0 home win over luckless Tregonissey ‘C’. Brother Ben and Charlie Prynn, Matt and Joe Chesterfield and the Predator Tregale were their winners to give the top of the table a very interesting look. Bethel ‘C’ are also joint second after defeating St Stephen ‘B’ 4-1. Josh Doherty got the home side off to the best start defeating Courtney Crockford but fairly easy wins for Ben Stunnell, Roger Smithson, Howard Brett and Rich Allen laves them in a good position with a game in hand on the others at the top. New Lerryn players Dave Davis and Oliver Rounsevell both won along with Terry Middleton and Charles McMiram to give Lerryn an excellent 4-1 win over Gorran Haven. Lee McKinstry beat Graham Hoskin to remain unbeaten for the season and register the away point.

FULL RESULTS

Victory League: Pelynt 2 (P Ormand (34 clearance), J Daniell) Bugle ‘A’ 3 (P Sturtridge, A Best, I Ball (37)), Bugle ‘B’ 0 St Blazey ‘A’ 5 (S Dewings, N Kendall, A Maxwell-Craddock, M Craddock, M Meares), Mevagissey ‘B’ 1 (M Gregory) Tregonissey ‘A’ 4 (M Woodward, M Knight, J Cocks, B McIntosh), Bethel ‘A’ 5 (L Collard, G Hawken, M Green, G Stephens, A Peers) St Stephen ‘A’ 0. Rees Memorial League: St Stephen ‘B’ 1 (J Doherty) Bethel ‘C’ 4 (B Stunnell, R Smithson, H Brett, R Allen), Lerryn 4 (D Davis, T Middleton, C McMiram, O Rounsevell) Gorran 1 (L McKinstry), Mevagissey ‘C’ 5 (M Chesterfield, D Tregale, B Prynn, C Prynn, J Chesterfield) Tregonissey ‘C’ 0, Tregonissey ‘B’ 2 (M Hooley, P Hooley) Bethel ‘B’ 3 (R Bolt, G Buckle, C Stuthridge). Additional Information League Tables Rankings Competitions Breaks Top breaks of the week: P Ormand 34, I Ball 37 Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('It''s big breaks all round', 'its-big-breaks-all-round', 'Match Reports', '[]'::jsonb, 'It was a big break on Tuesday as no fewer than seven breaks of over 30 were recorded.', null, '"Tregonisey ‘B’ stay equal top after seeing off Mevagissey ‘D’ with father and son Phil and Justin Hooley both winning as did Ryan Thomas, Rich Lakeman and James Tomlinson on target for the Meva boys."', 'It was a big break on Tuesday as no fewer than seven breaks of over 30 were recorded.

more Lostwithiel ‘A’s Darren Lock led the way with a 38 and a season’s league highest of 80 to help his team record a good 3-2 home win over Bugle ‘B’. Defending champions Bugle ‘A’ dropped two points at home to St Blazey ‘A’ Andrew Best had two breaks of 47 and 31 with Matt Woodward replying with a 38 when defeating Ian Powell. Tregonissey ‘A’ recorded a 5-0 whitewash at Bethel ‘C’ with Barry McIntosh’s 70 in the final frame compounding the home side’s misery as they played better than the score. Bethel ‘A’ lost out on two black ball games as they lost at St Blazey ‘B’ who continue to struggle for consistency but Mike Hancock had a welcome return to form with an excellent 50. The Rees League looks to be a very tight affair this year. Early leaders Bethel ‘D’ dropped two points at St Stephen ‘B’ with Jon Rosveare and Brad Christian winning for the home side, they are getting better with every game. Tregonisey ‘B’ stay equal top after seeing off Mevagissey ‘D’ with father and son Phil and Justin Hooley both winning as did Ryan Thomas, Rich Lakeman and James Tomlinson on target for the Meva boys. St Stephen ‘A’ travelled to Gorran Haven and recorded a 4-1 victory to sit third in the table. Andy Reddal got the better of Stacey Hancock in the final frame. Graham Hoskin remains unbeaten for Lerryn. His was the only point as they fell to a 4-1 loss at Bethel ‘B’ who moved up to joint fifth. The top match of the night saw Mevagissey ‘C’ inflicting a first defeat on Lostwithiel ‘B’ who are many people’s favourites for the title. Josh Daniell and Richard Broad scored for the away side, but Matt Chesterfield’s victory by a solitary point over Len Flower, was the decider on the night. All cup competition draws have now been made and sent out to all clubs.

FULL RESULTS

Victory League: Bugle ‘A’ 3 (A Best 47+31, P Sturtridge, G Spencer) St Blazey ‘A’ 2 (M Meares, M Woodward (38)), Lostwithiel ‘A’ 3 (C Dickinson, S Courts, D Lock (38+80)) Bugle ‘B’ 2 (J Moore, I Ball), Bethel ‘C’ 0 Tregonissey 5 (J Cocks, R Bilson, M Knight, C Stephenson, B McIntosh (70)), St Blazey ‘B’ 3 (G Taylor, P Baron, M Hancock (50)) Bethel ‘A’ 2 (M Green, G Stephens). Rees Memorial League: Gorran Haven 1 (A Reddal) St Stephen ‘A’ 4 (J Bennett, C Clark, A Harrison, A Garside), Mevagissey ‘C’ (J Chesterfield, D Kendall, M Chesterfield) Lostwithiel ‘B’ 2 (J Daniell, R Broad), Tregonissey ‘B’ 3 (J Hooley, P Hooley, R Thomas) Mevagissey ‘D’ 2 (R Lakeman, J Tomlinson), Bethel ‘B’ 4 (G Buckle, R Allen, M Sweet. C Stuthridge) Lerryn 1 (G Hoskin), St Stephen ‘B’ 2 (Jon Roseveare, B Christian) Bethel ‘D’ 3 (A Spearman, R Tonkin, J Pascoe). Top breaks of the week: A Best 47, 31, M Woodward 38, D Lock 38, 80, B McIntosh 70, N Hancock 50 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('It''s getting tight at the top', 'its-getting-tight-at-the-top', 'Match Reports', '[]'::jsonb, 'The big game of the night in the St Blazey and District Snooker League saw Tywardreath ‘A’ sneak past Bugle ‘A’ 3-2 to close the gap at the top of the table to five points with a game in hand.', null, '"Champions elect St Blazey brushed aside Twyardreath ‘B’ 5-0 and now only need eight points from their last four games to clinch the title."', 'The big game of the night in the St Blazey and District Snooker League saw Tywardreath ‘A’ sneak past Bugle ‘A’ 3-2 to close the gap at the top of the table to five points with a game in hand.

more Tregonissey joined the Legion boys on 49 points after despatching Lostwithiel ‘B’ 4-1 with Len Flower having another solid performance to claim the away side’s point. The only two breaks of the night both came in the same frame as Ian Ball’s 31 was good enough to see off Martin Rowe’s 34 as Bugle ‘B’ pulled off a surprise 4-1 win over St Neot. Both Mevagissey sides suffered 3-2 defeats with the ‘A’ side going down as Lostwithiel ‘A’ and Bodmin Sparks moved off the bottom of the league with a fine victory at Mevagissey ‘B’ as the old boys brigade of Mike Williams, Mike Bolt and Steve Bampton brought home the bacon. Gorran Haven picked up their fourth victory of the campaign defeating Lerryn 3-2 with the dependable Lee McKinstry amongst their marksmen. Bethel ‘D’ cemented second place with a 3-2 victory at Bugle ‘C’ with Vince Hathway, Ryan Tonkin and Jason Pascoe on target. But Bethel ‘B’s season is going the wrong way as a 3-2 defeat at Mevagissey ‘C’ which all but ends their promotion challenge. Champions elect St Blazey brushed aside Twyardreath ‘B’ 5-0 and now only need eight points from their last four games to clinch the title.

FULL RESULTS

Victory League: Lostwithiel ‘A’ 3 (D Lock, D Grose, C Perring) Mevagissey ‘A’ 2 (R Lakeman, M Towsey), Tywardreath ‘A’ 3 (D Kirwan, L Sturtridge, A Gooch) Bugle ‘A’ 2 (A Peers, A Best), Tregonissey 4 (C Kendall, R Bilson, C Stephenson, B McIntosh) Lostwithiel ‘B’ 1 (L Flower), Mevagissey ‘B’ 2 (D Kendall, M Gregory) Sparks 3 (M Williams, M Bolt, S Bampton), Bugle ‘B’ 4 (D Rundle, C Rundle, J Moore, I Ball (31)) St Neot 1 (M Courts. NSB - M Rowe (34)). Rees Memorial League: Lerryn 2 (G Hoskin, D Vipond) Gorran Haven 3 (L McKinstry, P Grimmett, A Rendall), St Blazey 5 (C Brown (39), M Woodward, L Rosevear, M Meares, C Reynolds) Tywardreath ‘B’, 0 Mevagissey ‘C’ 3 (D Tregale, J Chesterfield, B Prynn) Bethel ‘B’ 2 (M Green, M Sweet), Bugle ‘C’ 2 (J Moore, K Moore) Bethel ‘D’ 3 (V Hathway, R Tonkin, J Pascoe). Top breaks of the week: Martin Rowe 34, Ian Ball 31. Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('It’s getting tighter at the top after Bugle win', 'its-getting-tighter-at-the-top-after-bugle-win', 'Match Reports', '[]'::jsonb, 'Bugle ‘A’ had a great win at Tregonissey ‘A’ which enabled Mevagissey ‘A’ to close the gap on the table toppers after defeating St Blazey ‘B’.', null, '"Tregonissey ‘B’ have moved up to equal fourth thanks to a fine 4-1 victory at Bugle ‘C’. Nigel Couchman put Bugle one up but wins for Phil Hooley, Sam Simon, Chris Robins and Justin Hooley took the points back to Treggy."', 'Bugle ‘A’ had a great win at Tregonissey ‘A’ which enabled Mevagissey ‘A’ to close the gap on the table toppers after defeating St Blazey ‘B’.

more Bugle started well with Andy Peers seeing off Ryan Bilson. Wins for Barry McIntosh, Chris Stephenson and Ian Powell left Gary Spencer’s pivotal 48 break in the last frame seeing them home, Spencer beating Jason Cocks. Pete Chambers, Paul Williams and Matt Mills were Meva’s victors over St Blazey ‘B’ with Mike Hancock and Andrew Hooch replying. With eight games left Meva will hope to put more pressure on Treggy in the coming weeks. Bethel ‘A’ suffered a 4-1 home defeat to Lostwithiel. Gary Stephens got Bethel’s point defeating Anthony Maddams with Darren Lock’s excellent 52 break the highlight of the evening. Mevagissey ‘B’ moved off the bottom of the table thanks to Nathan Shaw’s victory over Matt Woodward but that was their only point as they went down 4-1 at St Blazey ‘A’ as Mickey Meares, Stewart Dewings, Leigh Rosevear and Nick Kendall were victorious for the home side. In the Rees League leaders Lostwithiel ‘A’ continued their relentless surge towards the title dispensing Bethel ‘B’ 4-1. Jim Tamblyn’s victory over captain John Daniell was the away side’s only bright spot with Richard Broad hitting a 32 break for the champions elect. Tregonissey ‘B’ have moved up to equal fourth thanks to a fine 4-1 victory at Bugle ‘C’. Nigel Couchman put Bugle one up but wins for Phil Hooley, Sam Simon, Chris Robins and Justin Hooley took the points back to Treggy. Mevagissey ‘D’ may be left to rue dropping two points at home to St Stephen ‘B’. Craig Nicholls and Rob Garside took the away points with the impressive Adam Pollard, James Tomlinson, with a 30 break, and Rob Blamey the home team’s winners. Mevagissey ‘C’ are slipping rapidly down the table, not helped by a 4-1 reverse at St Stephen ‘A’. Bennett, Allen, Harrison and Clarke on target for the home side with the predator Tregale on the ball for Meva. Lerryn slipped to a close 3-2 home defeat to Gorran Haven. Graham Hoskin and Gordon Brimcombe had put the home side 2-1 up but wins for Paul Grimmett and Rob Holmes following up Lee McKinstry’s victory took the points back beyond Mevagissey.

FULL RESULTS

Victory League: St Blazey ‘A’ 4 (M Mears, S Dewings, L Rosevear, N Kendall) Mevagissey ‘B’ 1 (N Shaw), Mevagissey ‘A’ 3 (P Chambers, P Williams, M Mills) St Blazey ‘B’ 2 (M Hancock, A Gooch), Tregonissey ‘A’ 2 (B McIntosh, C Stephenson) Bugle ‘A’ 3 (G Spencer (48), A Peers, I Powell), Bethel ‘A’ 1 (G Stephens) Lostwithiel ‘A’ 4 (C Dickenson, D Lock (52), S Courts, C Perring). Rees Memorial League: St Stephen ‘A’ 4 (J Bennett, D Allen, A Harrison, C Clark) Mevagissey ‘C’ 1 (D Tregale), Bugle ‘C’ 1 (N Couchman) Tregonissey ‘B’ 4 (S Simon, P Hooley, C Robins, J Hooley), Lostwithiel ‘B’ 4 (G Lory, L Flower, R Broad (32), A Parnell) Bethel ‘B’ 1 (J Tamblyn), Mevagissey ‘D’ 3 (A Pollard, J Tomlinson (30), R Blamey) St Stephen ‘B’ 2 (C Nicholls, R Garside), Lerryn 2 (G Hoskin, G Brimicombe) Gorran Haven 3 (L McKinstry, P Grimmett, R Holmes). Top breaks of the week: G Spencer 48, D Lock 52 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Jimmy White at 50', 'jimmy-white-at-50', 'Professional Snooker', '[]'::jsonb, 'Jimmy White isn''t at the Crucible this year, indeed it remains to be seen whether he will ever play there again in the World Championship.But for many he is synonymous with the event, for the drama and rollercoaster…', null, '''The Whirlwind'' was an attacking bundle of joy in his pomp. He has carted off over 20 trophies in 30 years in snooker, but his happiness was also his handicap: White has always been more about entertaining than winning. He hits his 50th birthday in May, with a testimonial lunch and dinner staged at the Grosvenor Hotel in London to mark his career a month later."', 'Jimmy White isn''t at the Crucible this year, indeed it remains to be seen whether he will ever play there again in the World Championship.But for many he is synonymous with the event, for the drama and rollercoaster ride he gave his many fans for the best part of two decades.

more White turned 50 today. It doesn''t seem that long since he was the pale-faced kid with a shot-making genius which rivalled that of his great friend Alex Higgins and the common touch which made him effortlessly popular with a generation of snooker fans. The teenage White bunked off school to play snooker and his head teacher eventually condoned his truancy on the basis that at least he knew where he was. White''s talent was obvious and he became English amateur champion at 16 and world amateur champion at 18. In his first season as a professional in 1981 he qualified for the Crucible, losing only 10-8 to Steve Davis.

NO PLANS TO GIVE UP YET

The following year he played what remains one of the Crucible''s greatest ever matches, poised for a place in the final at the age of 20 when he led Alex Higgins 15-14 and 59-0. But Higgins produced a miracle match saving clearance and won the decider too to deny White. Many felt it would only be a matter of time until the man nicknamed the Whirlwind won the biggest title of them all but it wasn''t to be. He came back strongly from 12-4 down to Davis in the 1984 final but was beaten 18-16. It took White six years to reach another world final where the ultra attacking game he had pioneered and Stephen Hendry taken to another level was apparent by the speed of their match - average frame time 12 minutes. Hendry won that one 18-12. In 1992 he came from 14-8 down to beat White 18-14. In 1993 he drubbed him 18-5 with a session to spare. Then in 1994, the biggest sickener of all, when White snatched at a black at 17-17. Hendry, of course, cleared up again. White had also lost to John Parrott 18-11 in 1991. There were to be no more finals, although he did gain a satisfying 10-4 first round victory over Hendry in 1998. It would be wrong to define White purely by his six world final defeats. He won the Masters in 1984. He was UK champion in 1992. He made a Crucible 147 earlier that year. He won ten world ranking titles, including the 2004 Players Championship at the age of 41. But more than all of that, he provided his vast array of supporters with an emotional connection to snooker. It wasn''t about pure results, it was about the journey. It was about Jimmy. White would never claim to have been a model professional. He had those essential flaws associated with the truly gifted. Maybe if he could he would go back in time and change the way he prepared for tournaments. But he can''t. All he can do is look forward, and he does because he isn''t finished with snooker yet. He is still very popular on the exhibition circuit and of course he is still playing on the main tour. He practises hard and still loves the game as much as ever. Snooker should raise a glass to Jimmy White on his 50th birthday. He remains one of the game''s greatest characters: an irrepressible working class hero whose tumultuous thrill-ride through the decades has kept many a fan coming back for more. Article courtesy of the Snooker Scene Images Courtesy of: David Levene', '2014-01-01', false, 'Richard Pearson'),
  ('Judd Top Trump in Llandudno', 'judd-top-trump-in-llandudno', 'Professional Snooker', '[]'::jsonb, 'Judd Trump has clinched the Ladbrokes Players Championship title after defeating Marco Fu 10-8 in Llandudno', null, '“I was kind of gone in the afternoon session and missing everything. I managed from somewhere to make those two centuries and get back into the game,” said the seven-time ranking winner.', 'Judd Trump has clinched the Ladbrokes Players Championship title after defeating Marco Fu 10-8 in Llandudno

more The significance of Trump’s victory is underlined by the fact that it’s only his second ranking title on British soil, after the 2011 UK Championship. The £125,000 top prize is also his joint highest career payday alongside that UK title and reaching the 2011 World Championship final. The triumph elevates Trump above Stuart Bingham to second in the world rankings. Fu’s attention will now turn to next month’s World Championship. The Hong Kong potter can now begin his preparations having failed to qualify for the China Open. He will head into the Crucible as one of the season’s most successful players having won the Scottish Open and reached a further two semi-finals, as well as being runner-up here in Llandudno. Fu dominated much of the afternoon session, but was pegged back by two consecutive centuries from the Ace in the Pack, to have his lead reduced from 5-2 to 5-4. Trump carried that momentum forward into this evening. He started at a blistering pace, winning four frames in a row, with runs of 110, 63 and 76 along the way to leading 8-5. Fu struggled to find the form he displayed earlier in the tournament, but the pendulum swung again as the world number nine edged back into the match. He moved within two at 8-6, before a dramatic 15th frame. Trump looked set to go one from victory, before an unexpected miss on the final pink allowed Fu to clinch the frame and make it 8-7. Lesser players could have folded following the disappointment of a miss like that, but Trump responded in emphatic fashion. He potted 12 reds with blacks and looked on for a maximum, before running out of position on 96 and being forced to take a blue. Trump’s run ended on 104. The Scottish Open Champion Fu stayed alive in the match thanks to a contribution of 58. However, Trump made contributions of 49 and 53 in the 18th frame to secure the title 10-8. Trump reflected: “It’s a great feeling, especially in this competition. It’s the 16 best players of the season. To win this one is probably up there with the UK Championship. This tournament has a lot of prestige and I’m delighted to have won.” “I was kind of gone in the afternoon session and missing everything. I managed from somewhere to make those two centuries and get back into the game,” said the seven-time ranking winner. “It was a little bit different tonight. The first frame was quite important and I managed to nick that. Then it changed around and he was missing everything. “It gives you a massive amount of belief to win tournaments like this. When you are a part of the latter stages of most events, you are in the mix and know your form is there. I’m not going to lose that between now and the worlds.” After the match Fu admitted that the burst from Trump to snatch control in the middle of the match was pivotal. “I didn’t do a lot wrong to go from 5-2 to 7-5,” said Fu. “Judd can win two or three frames in a row with big breaks so that’s not a surprise to me. I was kind of in control but in a long match you need to do a little bit more. Tonight it wasn’t quite enough to beat Judd.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Judd Trump: Box Office', 'judd-trump-box-office', 'Professional Snooker', '[]'::jsonb, 'Judd Trump is box office. The The 22-year-old Bristolian’s rapid, attacking play, audacious shot selection and penchant for the long pot means he has been carrying the ‘most exciting new talent since Ronnie…', null, '"A lot of the players are just there to win, and win even if it''s not pretty. I am aware of the crowd, the need to get them motivated and involved. I try and put on a show for the crowd and make sure they enjoy it."', 'Judd Trump is box office. The The 22-year-old Bristolian’s rapid, attacking play, audacious shot selection and penchant for the long pot means he has been carrying the ‘most exciting new talent since Ronnie O’Sullivan’ tag around with him almost since he turned professional five years ago.

CRAZY HAIRSTYLES & ENGAGING THE CROWD

And, last year, Trump started to live up to his billing. He outplayed John Higgins for much of the World Championship final, firing in two centuries to build a 10-7 lead and then making breaks of 104 and 99 to go 12-9 up. Higgins eventually prevailed, rallying to take a fourth world title 18-15, but was quick to credit his victim with playing “a brand of snooker I have never seen before”. Trump’s performance was credited as being the chief driving force behind the BBC’s highest viewing figures for the final in five years. That was more than enough to get the headline writers and snooker supremo Barry Hearn excited. But the boy-band hair, ‘maverick’ bow tie and referring to himself as an ‘international playboi’ on Twitter, coupled with a throwaway remark during this year’s Masters, led to comparisons with another nonconformist: Manchester City’s erratic-in-every-way striker Mario ‘Box Office’ Balotelli. “I said I kind of like Balotelli,” says Trump, by way of explanation. “He’s just himself and he doesn’t change for nobody. Obviously I don’t want to be him — I want to be myself. But I do admire some of the stuff he does. He’s just so cool about it.” So, no setting off fireworks, then? “No. I’m not that kind of person.” You can see why the comparison is tempting. Trump even arrives for our interview in his red Spider F430 convertible Ferrari (we hear him before we see him), which he parks up outside his snooker club. But as soon as he walks in, it’s clear that he is not that kind of person at all.

TABLE MANNERS

Quiet and unfailingly polite, Trump seems almost bewildered by the attention he receives as he obligingly tries on different suits for the camera and sportingly lies flat out on one of the club’s tables. The ‘club’ is not, as we had imagined, a dark, smoky back room guarded by a passive-aggressive barman. Instead, it’s a modern office unit set in a quiet business park on the outskirts of Romford, out of which Trump’s manager, Django Fung, operates. It’s also where he happens to have five championship-standard snooker tables. The tables — and the ‘green room’ next door, complete with a view of the adjacent B&Q — are there exclusively for the use of the small stable of players managed by Fung, including O’Sullivan and Trump’s 20-year-old flatmate, Jack Lisowski. The pair live “five minutes down the road”, with Trump uprooting from his native Bristol to find a better standard of practice competition and improve his game nearly two years ago. He describes the move as “a bit of a gamble”, but it seems to be paying off. To that World final, he can add the semi finals of this year’s Masters — beating O’Sullivan along the way — as well as victories at last year’s China Open and the UK Championship in December. “It was a little bit of a gamble,” he repeats, for emphasis. “But I wasn’t improving where I was. It’s good fun up here. It’s nice to get away from the parents and just do what you want to do. I do miss them now and again, but it’s nice to have your freedom.” Is there a danger, then, of that freedom having a detrimental effect — especially with the lure of a The Only Way is Essex social life, as well as London a quick Ferrari ride away? “It can be hard to dedicate yourself,” admits Trump. “But this is what I’ve wanted to do my whole life and I know this is the age when I have to knuckle down and do what I’ve got to do. We’re pretty good, we don’t go out that often... and we know snooker comes first.” He’s certainly dedicated, practising as often as seven days a week during the season, unless he is away playing in a tournament. “It’s down to us,” he says. “If we’re doing really well, we can ease off the practice and still do well in tournaments. But if we start losing then we’ve really got to try and punish ourselves, get in here every day and sort it out.” Trump speaks with a level of maturity that makes it easy to forget he is only 22. Maybe it comes with the quiet confidence honed by winning tournaments against grown men as an eight-year-old at Bristol’s Keynsham Snooker Centre. Or perhaps it’s a by-product of being talked about — by Steve Davis, no less — as the spearhead for the next generation of snooker stars. Does he feel a sense of responsibility to be the poster boy Hearn would so dearly like? “Yeah. You don’t want to make a fool out of yourself, but you want to promote the game and not say too many stupid things. [You want to] enjoy yourself and show people that it’s good fun what you’re doing and get other people into the game. Snooker doesn’t get half the publicity most other sports get, so it’s hard. And when snooker isn’t in the limelight, you’ve got to promote it to the best of your ability. “There are times when you’re getting beat, you’re not playing well and you’re sat on your chair, and you just want to pick up your chair and throw it on the table and just get out of there. But you’ve got to look like you’re enjoying it, and I think people take to that when you do.”

SNOOKERS SAVIOUR?

What about reading headlines labelling him ‘snooker’s saviour’ — does that expectation weigh him down? “I just ignore it, really,” says Trump. “It’s good to be known as that, but there have been a lot of players in the past who have had that label and kind of underachieved, so I don’t want to be like that — I want to be known as someone who achieved his potential.” ‘The Ace’ (though he much prefers “just Judd”) smiles and shrugs when Sport asks him what that potential might be. He will expand on his ambitions, though — namely, the World Championship. “Everyone wants to be world champion,” he says. “I don’t think you’re truly remembered unless you win the World Championship. That’s something I want to do, and quite early on. And then get to number one, and hopefully stay there for four or five years.” Is he confident of making a start on that this year? “I feel good,” says Trump. “This year has gone so fast for me — it’s been like a rollercoaster. It’s going to be nice to get back there and get involved. It’s the biggest three weeks of my life coming up, so hopefully I can do what I did last year and go one step further. The main thing is to go out and enjoy it, and hopefully let the fans enjoy it again. “I’m playing a lot better than last year, and I feel I’m a better player. These past three or four tournaments I’ve been playing well and losing only by the odd frame, and the people I’ve been playing have been going on to win. I feel like my form’s there — I’ve just got to try and turn it on and get a spark from somewhere.” Trump agrees when we suggest that those three weeks last year changed his life. “Yeah. To people outside of snooker it was a bit of a shock to them. A lot of people didn’t know me then, even though I won a few tournaments before that. That was kind of the rise of me, that tournament, with the publicity the World Championship gets. It really got my name out there and I got a big following from it.” Part of the final’s story was that it marked the culmination of Higgins’ return to the game from a six-month ban after he failed to report an illegal approach (revealed by the News of the World to be a set-up by the tabloid). How aware of that was Trump, and did it have an effect on him? “I knew it was going on, but I tried to blank it out and just play John Higgins,” he says. “He’s a great player. Obviously he wasn’t proven guilty, so you just have to get over it and just play him as a snooker player.” Despite that subplot, it seemed, for a while, as if Trump’s name was on the trophy. He qualified to beat defending champ Neil Robertson in the first round and stormed through the draw to dismantle world number four Ding Junhui in front of a raucous crowd in the semis. In doing so, Trump became, at 21 years and nine months, the second-youngest player to appear in a Crucible final. Only seven-time champion Stephen Hendry — the Scot was 21 and four months in 1990 — got there sooner. “From the Robertson game on, I felt really relaxed for the rest of the tournament and just thought ‘no pressure’,” reflects Trump. “I felt like I was invincible at some points. I just went out and played shots that some people thought were stupid, but at the time I felt like I was going to pot them, so I took them on. And people seemed to enjoy that.” Might this year present a different challenge? Trump nods: “Yeah. A lot of people are going to expect a lot of me this year. Last year was probably a one-off — some of the balls I was potting and stuff like that — and this year’s going to be a lot harder. There’s going to be a lot of people who want to beat me and try extra hard to beat me and bring me down. I’ll probably have to change my game a little bit and not take on so many balls. But when they’re there I’ll take ‘em — and when they’re not, I’ll play safe.” Trump admits that playing safe is not a decision he makes easily — especially when a pot, however difficult, is on. “At the time, if I feel it’s right, then I take it on,” he says. “Obviously if you watch it back, you can see it’s perhaps the wrong shot. But if you’re out there in the moment, you’ve just got to do what your heart tells you.”

THE ART OF ENTERTAINMENT

His words echo those of artist and snooker aficionado Damien Hirst, who has declared himself a fan. Trump, says Hirst, plays with “a lot of emotion”. Does he agree? “I just go out and whatever I see, I do,” he says. “There’s no scientific approach to it. I try to get the crowd to enjoy it and get them involved. At the end of the frames I take on shots that other players wouldn’t like to try and get the crowd on my side, and that’s a big part of it — having the crowd on your side helps a lot.” How did Trump feel, then, after being beaten by Robertson in an unsociable Masters semi final earlier this year, when the Australian suggested he was inspired by what he considered to be the unsporting behaviour of a group of rowdy Trump supporters? “I just think it’s jealousy, really,” says Trump. “I’ve had a lot of the limelight over the past year, and other players don’t really like that. For him to do that, there was no real reason for it. I think because I beat him in a couple of big tournaments, he just didn’t like it and he wanted to have his say about it. He wouldn’t have said that to someone like Ronnie, and Ronnie gets 10 times more support than I do.” Ah, Ronnie. It seems that, to follow in the Rocket’s footsteps, Trump first has to beat him in more or less every tournament he enters — the pair are more often than not drawn together in the latter stages of the bigger competitions (including the Masters quarters, which Trump won). Does he find it difficult to play O’Sullivan — a player he so looks up to? “First couple of times I played him I was really nervous and found it really difficult having the whole crowd on his side,” he admits. “It’s not a nice place to be when you’re sat on your chair and he’s at the table and everyone’s cheering him on. But the older I’ve got and the more I’ve seen him, it’s become a lot easier. I see it as a bit of a challenge when he has the support — I try and get a few of the crowd on my side. “But I feel I really need a big occasion to play my best. I really enjoy playing on the TV now in front of people, whereas a couple of seasons ago I found it hard to enjoy and real nerve-wracking. Now all I want to do is be in front of the cameras. I feel I really raise my game in front of the bigger crowds.” Trump will be hoping he can do just that and claim the world title in front of a packed Crucible three weeks from now. At 5/1 with the bookies, and for an ever-increasing crowd, Trump is the favourite. Article courtesy of the Sport Magazine Images Courtesy of: David Levene & Action Images', '2014-01-01', false, 'Richard Pearson'),
  ('King crowned in Belfast', 'king-crowned-in-belfast', 'Professional Snooker', '[]'::jsonb, 'Mark King has won his maiden ranking title following a remarkable 9-8 victory over Barry Hawkins at the Coral Northern Ireland Open in Belfast.', null, 'King said: “At 8-7 up my little daughter Polly was doing cartwheels outside and it just calmed me down seeing her happy. I thought to myself worst case scenario I have my three gems here and my wife. I left everything on the table and it is nice to come out and be a champ.', 'Mark King has won his maiden ranking title following a remarkable 9-8 victory over Barry Hawkins at the Coral Northern Ireland Open in Belfast.

more The win had looked unlikely with King trailing 5-1 during the opening session. However, he crucially clawed it back to 5-3 at the break. King then won the first four frames when they returned in the evening to lead 7-5 in a remarkable turnaround. He blasted to the front with breaks of 62, 100, 45 and 53. There were then scenes of pure drama as Hawkins fought back. With King 8-7 ahead, he required one seven-point snooker on the colours to tie. The black ball had come to lie perilously over edge the bottom pocket and King ambitiously embarked upon trying to lay the object ball on top of it. He eventually achieved that thanks to one of the shots of the tournament, cross doubling the pink the length of the table. Hawkins fouled the black and his opponent forced a re-spot. King narrowly missed a double to middle for the title and allowed the Hawk in to force a decider. After a match filled with fluent break building the final frame was understandably tense. Both players had and missed chances. However, it was King who forced himself over the line and emotionally embraced his family as they entered the arena. The scenes were reminiscent of the man who the trophy was named after Alex Higgins, who had beckoned his then baby daughter Lauren onto the Crucible floor in 1972 after winning the world title. Lauren was present today, 44 years on, and handed over the trophy to an emotional King. King said: “At 8-7 up my little daughter Polly was doing cartwheels outside and it just calmed me down seeing her happy. I thought to myself worst case scenario I have my three gems here and my wife. I left everything on the table and it is nice to come out and be a champ. “I just thought all week my name was on the trophy. I haven’t said it but things were happening. People were missing game balls on the black. I just think it was meant to be,” said King. “The money is always nice. I came here and I don’t think I had a tenner in the bank. My dad and my mate lent me a few quid and hopefully I can build on it now.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Kyren''s Shanghai Surprise', 'kyrens-shanghai-surprise', 'Professional Snooker', '[]'::jsonb, 'Kyren Wilson completed a remarkable triumph at the Bank of Communications Shanghai Masters by beating Judd Trump 10-9 in the final.', null, 'Judd put me under a lot of pressure from 9-7 down. He goes for his shots and you never feel safe against him. I got a half chance in the last frame with a red to a middle pocket and I just thought ‘this is my time.’ Luckily it went in and I cleared up.', 'Kyren Wilson completed a remarkable triumph at the Bank of Communications Shanghai Masters by beating Judd Trump 10-9 in the final.

more Wilson had never previously been beyond the quarter-finals of a ranking event, but went all the way to the £85,000 top prize at the Grand Stage in Shanghai. At 54th in the world he is one of the lowest-ranked players to win a full ranking title in snooker history. Dave Harold holds that record having been 93rd on the list when he won the 1993 Asian Open. There were few signs that Kettering’s 23-year-old Wilson might be a contender this week as he reached the last 16 of just one ranking event last season. He became a father for the first time in February, and his new-found maturity and dedication to practice has clearly paid dividends. He has captured his first pro title the hard way, winning three matches just to qualify for Shanghai, then beating wild card Wang Yuchen, Joe Perry, Michael Holt, home favourite Ding Junhui and Mark Allen before his dramatic win over Trump in an exciting final. Wilson, who turned pro in 2010, will surge up the ranking list as a result of this victory and is surely destined to lift many more trophies. He also earns a spot at the Champion of Champions in Coventry in November,. World number seven Trump was seeking his fifth ranking title from his ninth final but got off to a slow start and was never ahead. The first four frames were shared, Trump making the better breaks with 81 and 72. Wilson then pulled away to lead 6-3 at the end of the first session, compiling runs of 71, 58 and 62. He also claimed the first of the evening session and though Trump’s 115 gave him the 11th frame, Wilson replied with 68 to lead 8-4. Then came the Trump fightback as he won three in a row with top breaks of 76 and 50. Wilson made it 9-7 before Bristol’s 26-year-old Trump made 89 and 60 in getting to 9-9. But, despite his lack of experience at this level, Wilson remained calm and made a brilliant match-winning 75 in the decider. “It’s every player’s dream to win his first ranking title. It will always stay in my memory. This is my breakthrough, just like Judd had his when he won the (2011) China Open,” said Wilson, who only received the necessary visa on the day he flew to Shanghai last week. “I’ve got to stay grounded and keep practising hard. You’ve got to be so consistent to beat the top players. “I felt like crying at the end because it means so much to me. It felt as if it was slipping away from me, so to pull through in the end was just a relief. The fans were fantastic and the noise will live with me forever. “Judd put me under a lot of pressure from 9-7 down. He goes for his shots and you never feel safe against him. I got a half chance in the last frame with a red to a middle pocket and I just thought ‘this is my time.’ Luckily it went in and I cleared up. “I didn’t want it to go to 9-9 but you just have to stay in the present and deal with what is in front of you. There wasn’t much I could do from 9-7, I just had to stick in there and wait for a chance.” Former UK Champion Trump, who also lost the 2012 Shanghai final 10-9 to John Higgins, said: “I played so badly in the first session. Tonight I played ok but I threw a lot of frames away. I had more than enough chances to win, though I didn’t get one in the last frame and he made a really good break. It’s good to get to a final but disappointing to lose.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Leaders Bugle lose out on the road', 'leaders-bugle-lose-out-on-the-road', 'Match Reports', '[]'::jsonb, 'St Blazey and District Victory League leaders Bugle ‘A’ were toppled by the odd frame away at Lostwithiel ‘A’ as Steve Courts, Cyril Dickinson and Chris Perring recorded good victories.', null, '"St Stephen ‘A’ sit nicely in second place beating their ‘B’ side 4-1. Josh Doherty’s victory over Stacey Hancock gave his side their first point of the season but the more experienced ‘A’ team took the honours through Bennett, Clarke, Green and Harrison."', 'St Blazey and District Victory League leaders Bugle ‘A’ were toppled by the odd frame away at Lostwithiel ‘A’ as Steve Courts, Cyril Dickinson and Chris Perring recorded good victories.

more Bugle were indebted to Gary Spencer’s 45 clearance and Andrew Best seeing off Darren Lock for their points. Tregonissey ‘A’ climbed the table after beating Bethel ‘A’ 4-1 with Jason Cocks’ 43 and Barry McIntosh’s 32 helping to give a true reflection of the evening’s play. Mevagissey ‘A’ have jumped to the top of the table beating their ‘B’ team 5-0 with wins for Leighton Varcoe, Phil Staley, Matt Mills and Paul Williams and Chris beating Dave in the battle of the Kendalls. St Blazey ‘A’ turned over their own ‘B’ team 3-2 with excellent wins for Mickey Meares, Nick Kendall and Stewart Dewings with Andrew Gooch and Darren Kirwan replying. Richard Opie made a welcome return to the league by recording a 48 break helping Tregonissey ‘B’ thrash Bethel ‘B’ 4-1. Chris Robins, Justin Hooley and Rob Giltjes were also winners with Jim Tamblyn replying. Lerryn got their season underway with a 4-1 home defeat at the hands of Bethel ‘D’, who are pulling away at the top – the dependable Graham Hoskin notching the home point with victory over Shaun Hicks. George Lory scored 89 points in his frame as Lostwithiel ‘B’ returned from Bugle ‘C’ with a nap hand with Bryan Warne, Richard Broad, Josh Daniell and Lenny Flowers victorious. St Stephen ‘A’ sit nicely in second place beating their ‘B’ side 4-1. Josh Doherty’s victory over Stacey Hancock gave his side their first point of the season but the more experienced ‘A’ team took the honours through Bennett, Clarke, Green and Harrison. The Mevagissey derby went the way of the ‘D’ team – James Tomlinson notched for the ‘C’ team but Joe and Matt Chesterfield along with Mark Gregory and Charles Prynn gave the ‘D’ team the bragging rights. In a rearranged match on Thursday evening Tregonissey ‘B’ defeated Lerryn 4-1 to go equal top of the league Graham Hoskin winning again for the home team but Phil and Justin Hooley and Richard Opie and Chris Robins were victorious for the visitors.

FULL RESULTS

Victory League: St Blazey ‘A’ 3 (M Mears, S Dewings, N Kendall) St Blazey ‘B’ 2 (A Gooch, D Kirwan), Mevagissey ‘A’ 5 (C Kendall, L Varcoe, P Staley, M Mills, P Williams) Mevagissey ‘B’ 0, Tregonissey ‘A’ 4 (J Cocks (43), B McIntosh (32), C Stephenson, R Bilson) Bethel ‘A’ 1 (G Hawken), Lostwithiel ‘A’ 3 (S Courts, C Dickinson, C Perring) Bugle ‘A’ 2 (G Spencer (45cl), A Best). Rees Memorial League: St Stephen ‘A’ 4 (J Bennett, C Clark, B Green, A Harrison) St Stephen ‘B’ 1 (J Doherty), Bugle ‘C’ 0 Lostwithiel ‘B’ 5 (B Warne, G Lory, R Broad, J Daniell, L Flower), Mevagissey ‘D’ 1 (J Tomlinson) Mevagissey ‘C’ 4 (J Chesterfield, M Gregory, C Prynn, M Chesterfield), Lerryn 1 (G Hoskin) Bethel ‘D’ 4 (B Stunnell, R Tonkin, J Pascoe, A Spearman), Bethel ‘B’ 1 (J Tamblin) Tregonissey ‘B’ 4 (C Robins, J Hooley, R Opie (48), R Giltjes), Lerryn 1 (G Hoskin) Tregonissey ‘B’ 4 (R Opie, C Robins, J Hooley, P Hooley). Top breaks of the week: J Cocks 43, B McIntosh 32, G Spencer 45, R Opie 48 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Leaders drop two points on opening day of the season', 'leaders-drop-two-points-on-opening-day-of-the-season', 'Match Reports', '[]'::jsonb, 'The first week of the new season in the St Blazey and District Snooker League saw defending champions Tregonissey ‘A’ surprisingly drop two points at newly promoted Bethel ‘D’.', null, '"New sides Pelynt and St Neot met with the away side claiming a 4-1 win. Phil Ormond played well for Pelynt, thrashing Chris Perring 76-27 but wins for Cyril Dickenson, Darren Lock, Anthony Maddams and Steve Courts did the business for St Neot."', 'The first week of the new season in the St Blazey and District Snooker League saw defending champions Tregonissey ‘A’ surprisingly drop two points at newly promoted Bethel ‘D’.

more Great wins for Jason Pascoe over Ryan Bilson and Ross McMenemy’s over Jason Simmonds got the home team’s points with Chris Stephenson, Jason Cocks and Barrie McIntosh claiming victory. St Blazey ‘B’ have started strongly with a 5-0 victory over Bugle ‘B’ and their aim is to be more consistent this year in their title challenge – messers Taylor, Read, Hancock, Baron and Gooch their marksmen. Two great victories for Matt Green and Leon Collard over Pete Chambers and Paul Williams respectively gave Bethel ‘A’ two points at runners-up Mevagissey ‘A’ and it could have been better for Bethel but for Chris Kendall’s 25 clearance when 18 behind against debutant Andy Peers. Bugle ‘A’ have started strongly with a 4-1 home victory over St Blazey ‘A’ for whom Nick Kendall’s victory over promoted Ian Ball their only success. Gary Spencer produced a 35-break in his victory over Leigh Rosevear with further wins for Ian Powell, Andrew Best and Paul Sturtridge. New sides Pelynt and St Neot met with the away side claiming a 4-1 win. Phil Ormond played well for Pelynt, thrashing Chris Perring 76-27 but wins for Cyril Dickenson, Darren Lock, Anthony Maddams and Steve Courts did the business for St Neot. It promises to be a very interesting season ahead in the Rees League with five or six teams very much likely to be in contention. Bethel ‘B’ started strongly defeating Tregonissey ‘B’ 4-1. Martin Knight being the only home winner as Guy Buckle, Richy Allen, Jim Tamblyn and Clive Stuthridge, who switched from Bodmin Q Bar at the last minute, were the winners. The Mevagissey derby between the C and B teams started with predator Tregale easily sweeping away big Ben Rothwell but the ‘B’ team then claimed the remaining four frames through Nathan Shaw, Dave Kendall, Mark Gregory and Matty Rowe and will be a hard side to beat this year. Some very close frames at Lerryn who hosted Mevagissey ‘C’ saw the seasiders return home with a narrow 3-2 win. Dave Phipps and Gordon Brimicombe were on target for the home side with Neil Parker, George Lory, on his debut for the side, and Rich Lakeman on target for the Meva boys. Newcomers Bodmin Q-Bar started with a 3-2 home win over Gorran Haven. Matt Woodward, Richie Bolt traded frames with Andy Reddall and Richard Holmes leaving Steve Bampton to sneak past Lee McKinstry in the decider.

FULL RESULTS

Victory League: Mevagissey ‘A’ 3 (C Kendall, M Mills (38), P Staley) Bethel ‘A’ 2 (M Green, L Collard), Bethel ‘D’ 2 (J Pascoe, R McMenemy) Tregonissey ‘A’ 3 (C Stephenson, J Cocks, B McIntosh), Bugle ‘A’ 4 (I Powell, A Best, G Spencer (35), P Sturtridge) St Blazey ‘A’ 1 (N Kendall), Pelynt 1 (P Ormond) St Neot 4 (C Dickenson, D Lock, A Maddams, S Courts), St Blazey ‘B’ 5 (G Taylor, J Read, M Hancock, P Baron, A Gooch) Bugle ‘B’ 0. Rees Memorial League: Tregonissey ‘B’ 1 (M Knight) Bethel ‘B’ 4 (G Buckle, R Allen, J Tamblyn, C Stuthridge), Lerryn 2 (D Phipps, G Brimicombe) Mevagissey ‘D’ 3 (N Parker, G Lory, R Lakeman), Bodmin Q-Bar 3 (M Woodward, R Bolt, S Bampton) Gorran Haven 2 (A Reddall, R Holmes), Mevagissey ‘C’ 1 (D Tregale) Mevagissey ‘B’ 4 (N Shaw, D Kendall, M Gregory, M Rowe). Top breaks of the week: M Mills 38, G Spencer 35 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Leaders suffer first defeat', 'leaders-suffer-first-defeat', 'Match Reports', '[]'::jsonb, 'An out of sorts previously unbeaten St Blazey ‘B’ suffered a surprise 4-1 defeat at mid-table Bethel ‘A’ to blow the title race wide open.', null, '"Bert Bampton saw off Howard Brett to stop a whitewash as Bethel saw off Bodmin Sparks and Mevagissey saw off St Stephen, with Anthony Garside continuing his good run with victory over last week’s hero Dave Kendall."', 'An out of sorts previously unbeaten St Blazey ‘B’ suffered a surprise 4-1 defeat at mid-table Bethel ‘A’ to blow the title race wide open.

more The home side rode their luck to gain wins through Gary Stephens, Steve Allen, Leon Collard and Geoff Hawken and only Mike Hancock, who had a 30 break, was able to register for the tabletoppers whop have now been joined on 53 points by Bugle ‘A’ after their 4-1 home victory over Lostwithiel ‘A’. In-form Darren Lock saw off Andrew Best for the away point, with Gary Spencer’s excellent 54 clearing the highlight for Bugle. Mike Towsey’s final-frame victory over John Daniell saw Mevagissey ‘A’ return home from Lostwithiel ‘B’ with a 3-2 win, Richard Broad and Dave Grose on target for the home side. Bethel ‘D’ caused a major upset by going to third-placed Tregonissey and winning 3-2 as Steve Benallack, Ryan Tonkin and Andy Spearman upset the form book for a great victory. Ian Ball saw off Chris Brown to give Bugle ‘B’ a good start at St Blazey ‘A’, but Mickey Meares, Stewart Dewings, Matty Woodward and Nick Kendall secured the remaining frames to raise their side up to fourth place. In the Rees Memorial League, both Mevagissey ‘B’ and Bethel ‘C’ gained four points apiece in their matches and played each other last night in a match which could go a long way to settling the title. Bert Bampton saw off Howard Brett to stop a whitewash as Bethel saw off Bodmin Sparks and Mevagissey saw off St Stephen, with Anthony Garside continuing his good run with victory over last week’s hero Dave Kendall. Mevagissey ‘D’ scrapped home 3-2 over Gorran Haven with Richard Lakeman, Rob Blamey and Scott Mills victorious. Gorran’s point came through Rob Bunney and Lee McKinstry – who notched a 34-break. Ben Prynn notched a fine 32 break for Mevagissey ‘C’ and with brother Charlie and Joe Chesterfield also winning they claimed a 3-2 success at Bugle ‘C’ with Nigel Couchman and Kevin Spencer scoring for the Bugle boys.

FULL RESULTS

Victory League: Tregonissey 2 (B McIntosh, R Pearson) Bethel ‘D’ 3 (R Tonkin, S Benallack, A Spearman), St Blazey ‘A’ 4 (M Woodward, M Mears, S Dewings, N Kendall) Bugle ‘B’ 1 (I Ball), Bugle ‘A’ 4 (A Peers, P Sturtridge, G Spencer (54), I Powell) Lostwithiel ‘A’ 1 (D Lock), Lostwithiel ‘B’ 2 (R Broad, D Grose) Mevagissey ‘A’ 3 (L Varcoe, C Kendall, M Towsey), Bethel ‘A’ 4 (G Stephens, S Allen, L Collard, G Hawken) St Blazey ‘B’ 1 (M Hancock (30)). Rees Memorial League: Bugle ‘C’ 2 (K Spencer, N Couchman) Mevagissey ‘C’ 3 (B Prynn (32), C Prynn, J Chesterfield), Mevagissey ‘D’ 3 (R Lakeman, R Blamey, S Mills) Gorran Haven 2 (R Bunney, L McKinstry), Mevagissey ‘B’ 4 (M Rowe, N Shaw, B Rothwell, M Gregory) St Stephen 1 (A Garside), Sparks 1 (S Bampton) Bethel ‘C’ 4 (R Smithson, C Crockford, P Thomas, M Powell). Top breaks of the week: G Spencer 54, M Hancock 30, B Prynn 32 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('League season starts on Tuesday September 24th 2013...', 'league-season-starts-on-tuesday-september-24th-2013', 'Match Reports', '[]'::jsonb, 'The League Tables for the 2013/14 Season have been added, you can view them here on the St Blazey website: http://www.stblazeydistrictsnooker.co.uk/?page_id=529 or directly on the League Republic Website here:…', null, null, 'The League Tables for the 2013/14 Season have been added, you can view them here on the St Blazey website: http://www.stblazeydistrictsnooker.co.uk/?page_id=529 or directly on the League Republic Website here: http://stblazey.leaguerepublic.com/l/league/972702256.html Season starts on Tuesday September 24 2013 You can view all the fixtures here: http://www.stblazeydistrictsnooker.co.uk/?page_id=535', '2014-01-01', false, 'Richard Pearson'),
  ('Len blossoms on the road', 'len-blossoms-on-the-road', 'Professional Snooker', '[]'::jsonb, 'The first week of the new season of St Blazey and District snooker league produced seven matches that all finished 3-2.', null, '"Undoubtably the performance of the night came at the Lostwithiel derby where Len Flowers had a blooming good win"', 'The first week of the new season of St Blazey and District snooker league produced seven matches that all finished 3-2.

more Undoubtably the performance of the night came at the Lostwithiel derby where Len Flowers had a blooming good win by 61 points to 16 over Darran Lock. Defending champions Tregonissey (formerly St Blazey ‘A’) suffered a home defeat to Tywardreath ‘A’ with Andy Gooch beating Chris Kendall in the deciding frame. Bugle ‘B’ entertained newly promoted Mevagissey ‘B’ and won 4-1 with Matt Rowe saving the whitewash. Both newcomers to the Rees league Meva ‘D’ and Gorran Haven locked horns and there were some close frames with Meva eventually prevailing 4-1. Richard Holmes the solitary winner for the Haven.

FULL RESULTS

